-- เลนวิ่งเริ่มต้น  ตัวจริงที่ใช้คือ Hub.LaneZ ซึ่งขยับเองได้ (ดู Hub.pickLaneZ)
--
-- ทำไมไม่ฮาร์ดโค้ดหนีลูกวิ่ง:
