-- LOOPS
--==================================================================

-- ลูปฟาร์มหลัก
task.spawn(function()
	local lastLine
	while alive() do
		if Config.Running then
			local ok, err, success = pcall(cycle)
			if not ok then
				log("error:", err)
			elseif err then
				-- ตอนยืนรอไข่ดีๆ ข้อความจะซ้ำทุก 2 วิ ไม่ต้องถมล็อก
				if err ~= lastLine then log(err) end
				lastLine = err
			elseif success then
				log("✓ ส่งไข่เข้าฐานแล้ว")
				lastLine = nil
			end
			-- โหมดวาปทำงานจบรอบใน ~2 วิ ถ้ายังคั่น 2 วิเท่าเดิมคือเสียเวลาไปครึ่งหนึ่ง
			task.wait(Config.MoveMode == "warp"
				and math.min(0.3, tonumber(Config.LoopDelay) or 2)
				or Config.LoopDelay)
		else
			Hub.Phase = "พัก"
			task.wait(0.5)
		end
	end
end)

-- กระดานไข่ดีสุด
task.spawn(function()
	while alive() do
		pcall(function()
			local ranked = rankedEggs(Config.Area)
			local rows = {}
			for i = 1, 3 do
				local e = ranked[i]
				rows[#rows + 1] = e
					and ("%d. %s [%s] $%s/s"):format(i, e.rec.AssetCategory, e.rec.AreaId, comma(e.rate))
					or ("%d. -"):format(i)
			end
			setBoard(table.concat(rows, "\n"))

			-- ป้อนกระดานชุดเดียวกันให้ข้อความกลางจอ ไม่ต้องยิงรีโมทซ้ำ
			overlayBoard = "— ไข่ดีสุดในสนาม —\n" .. table.concat(rows, "\n")
			renderOverlay()
		end)
		task.wait(5)
	end
end)

-- แถบสถานะ
task.spawn(function()
	while alive() do
		pcall(function()
			local lvl, cap, money = baseInfo()
			local pets = #myPets()
			local text = ("%s  •  %d studs/s\nรอบ %d · ได้ %d · พลาด %d · ฟัก %d · ขาย %d · อัป %d\nฐาน Lv%s (%s ตัว) · มีสัตว์ %d · เงิน $%s")
				:format(
					tostring(Hub.Phase), math.floor(Config.Step / Config.Gap),
					Stats.cycles, Stats.stolen, Stats.failed, Stats.hatched, Stats.sold, Stats.upgrades,
					tostring(lvl), tostring(cap), pets, comma(money or 0)
				)
			local left = secondsToReset()
			if left then text = text .. ("\nรีเซ็ตอีก %ds"):format(left) end
			if isResetting() then text = text .. "  (กำลังรีเซ็ต)" end
			setStatus(text)
			setLogBox(recentLog(6))

			-- ข้อความกลางจอ: จัดใหม่ให้อ่านเร็วกว่าแถบใน UI
			-- บรรทัดแรกคือ "ตอนนี้ทำอะไรอยู่" ตัวใหญ่สุด ที่เหลือเป็นตัวเลขประกอบ
			local head = ("【 Hamsterdiwa 】 %s"):format(tostring(Hub.Phase))
			if not Config.Running then head = head .. "  (หยุดอยู่)" end
			if isResetting() then
				head = head .. "  · กำลังรีเซ็ตสนาม"
			elseif left then
				head = head .. ("  · รีเซ็ตอีก %ds"):format(left)
			end

			overlayHead = table.concat({
				head,
				("ได้ %d · พลาด %d · ฟัก %d · ขาย %d · อัปฐาน %d")
					:format(Stats.stolen, Stats.failed, Stats.hatched, Stats.sold, Stats.upgrades),
				("ฐาน Lv%s · คอก %s ช่อง · มีสัตว์ %d ตัว · $%s")
					:format(tostring(lvl), tostring(cap), pets, comma(money or 0)),
			}, "\n")
			renderOverlay()
		end)
		task.wait(0.6)
	end
end)

-- แผงสัตว์ในกระเป๋า
-- แยกลูปของตัวเอง เพราะต้องอ่านข้อมูลก้อนใหญ่ ไปปนกับแถบสถานะที่วิ่งทุก 0.6 วิ ไม่ไหว
task.spawn(function()
	while alive() do
		pcall(function()
			local list, total, keep = sellCandidates()
			local rows = { ("มีทั้งหมด %d ตัว · ในคอก %d · เข้าข่ายขาย %d")
				:format(total, equipCap(), #list) }
			for i = 1, math.min(4, #list) do
				rows[#rows + 1] = ("  %s  $%s/s"):format(list[i].cat, comma(list[i].mps))
			end
			if #list > 4 then rows[#rows + 1] = ("  ... อีก %d ตัว"):format(#list - 4) end
			if #list == 0 then rows[#rows + 1] = "  ไม่มีตัวเข้าข่าย" end
			setPets(table.concat(rows, "\n"))
		end)
		task.wait(10)
	end
end)

-- ลูปเซฟค่าถูกถอดออก  สคริปต์ไม่เขียนคอนฟิกลงดิสก์แล้ว
-- (markDirty ยังมีอยู่และ UI ยังเรียกได้ แต่ไม่มีใครอ่านค่านั้นต่อ = ไม่มีผล)

-- Anti-AFK
--
-- ของเดิมใช้ บริการจำลองอินพุตของ CoreScript ซึ่งเป็นวิธีมาตรฐาน
-- แต่ บริการจำลองอินพุต เป็นบริการต้องห้าม แค่เรียกก็โดนเตะข้อหาโกงใน 10 วินาที
-- (ดูบันทึกการวัดที่หัวไฟล์ ตรงที่ถอด GetService ออก)
--
-- แทนด้วยการขยับตัวเองนิดเดียวเมื่อเกมแจ้งว่าเราอยู่เฉยๆ นานเกินไป
-- Roblox นับ AFK จาก "ไม่มีอินพุต" แต่การขยับตัวละครก็รีเซ็ตตัวนับให้เหมือนกัน
-- ฟาร์มที่วิ่งอยู่ตลอดแทบไม่มีทางเข้าเงื่อนไขนี้ ตัวนี้เป็นแค่ตาข่ายกันเหนียว
local afkConn
pcall(function()
	afkConn = LocalPlayer.Idled:Connect(function()
		if not Config.AntiAFK or not alive() then return end
		pcall(function()
			local _, hrp = char()
			if hrp then
				hrp.CFrame = hrp.CFrame + Vector3.new(0, 0.15, 0)
				task.wait(0.15)
				hrp.CFrame = hrp.CFrame - Vector3.new(0, 0.15, 0)
			end
		end)
	end)
end)

--==================================================================
-- DESTROY
--==================================================================
function Hub.Destroy()
	Config.Running = false
	Hub.Alive = false
	-- ล้างเฉพาะตารางที่เลขตรงกับตัวเราจริงๆ
	--
	-- ของเดิมเช็ค genv แล้วล้างทั้งสองตารางพร้อมกัน
	-- แต่บาง executor คืน genv ใหม่ทุกครั้งที่รัน ตัวเก่าจึงเห็นเลขตรงกับตัวเองเสมอ
	-- พอมันปิดตัวเอง จะไปล้าง _G ซึ่งเป็นของสคริปต์ตัวใหม่ด้วย
	-- ตัวใหม่เห็นเลขกลายเป็น 0 ก็คิดว่าตัวเองล้าสมัยแล้วปิดตามไปอีก = ดับทั้งคู่
	if genv.EGG_FARM_GEN == GEN then genv.EGG_FARM_GEN = 0 end
	if _G.EGG_FARM_GEN == GEN then _G.EGG_FARM_GEN = 0 end
	pcall(setNoclip, false)

	-- ร่อนลงก่อนดับพื้นเสก ไม่ใช่ตัดทิ้งเฉยๆ
	--
	-- Destroy ถูกเรียกตอนรันสคริปต์ทับด้วย ถ้าตอนนั้นตัวกำลังบินอยู่ที่ y=82
	-- แล้วดับพื้นทันที ตัวจะร่วงแล้วตายทันทีที่โหลดตัวใหม่เสร็จพอดี
	-- ท่านี้ใช้เวลาราว 0.3 วิ ยอมรอได้
	pcall(stopSmoothCam)   -- คืนกล้องให้เกาะตัวละครตามเดิม ไม่งั้นกล้องค้าง
	if afkConn then pcall(function() afkConn:Disconnect() end) end
	if inputConn then pcall(function() inputConn:Disconnect() end) end
	pcall(destroyUI)
	pcall(function()
		if Hub.OverlayGui then Hub.OverlayGui:Destroy() Hub.OverlayGui = nil end
	end)
	genv.EGG_FARM_HUB = nil
end

--==================================================================
-- กล่องดำ  บันทึกสถานะลงไฟล์ตลอดเวลา
--
-- ทำไมต้องมี:
-- อาการ "โดนเตะ" เกิดเฉพาะบางเครื่อง และเครื่องที่ใช้พัฒนาไม่เคยเป็น
-- เดาจากภาพหน้าจอทีละใบแล้วผิดมาหลายรอบ เพราะไม่มีข้อมูลว่าตอนนั้นทำอะไรอยู่
--
-- ตัวนี้เขียนสถานะลงไฟล์ทุก 2 วินาที เก็บย้อนหลัง 150 บรรทัด (ราว 5 นาที)
-- พอโดนเตะ ไฟล์ยังอยู่ในเครื่อง เปิดอ่านได้ว่าวินาทีสุดท้ายทำอะไร
--
-- ไฟล์: HamsterTrace.txt ในโฟลเดอร์ workspace ของตัวรัน
-- ปิดได้ด้วย Config.Trace = false  (เขียนไฟล์เล็กมาก ไม่กินเฟรม)
--==================================================================
if Config.Trace ~= false and type(writefile) == "function" then
	task.spawn(function()
		local TRACE = "HamsterTrace.txt"
		local buf, MAX = {}, 150
		local t0 = os.clock()
		pcall(function()
			writefile(TRACE, ("=== Hamsterdiwa %s | %s | ver %d | job %s ===\n")
				:format(tostring(Hub.Build), tostring(Hub.Caps and Hub.Caps.executor),
					game.PlaceVersion, string.sub(tostring(game.JobId), 1, 8)))
		end)
		-- บันทึกสถานะของระบบกันโกงด้วย  นี่คือข้อมูลที่ต้องใช้จริงตอนไล่หาสาเหตุการเตะ
		--
		-- ของเดิมบันทึกแต่ตำแหน่ง/เลือด/ความเร็ว ซึ่งบอกไม่ได้เลยว่าระบบมองเรายังไง
		-- ตัวที่ต้องเห็นคือ ThreatLevel · Evidence.Speed · Evidence.Teleport
		-- · LastViolationReason · MovementMode · IsSupportedNow
		-- ถ้าโดนเตะแล้วค่าพวกนี้ยังสะอาด แปลว่าเซิร์ฟตัดสินเอง ไม่ใช่ฝั่งเรา
		--
		-- และเก็บ "ความเร็วเชิงตำแหน่งจริง" ด้วย เพราะนั่นคือสิ่งที่เซิร์ฟวัด
		-- ต่างจาก AssemblyLinearVelocity ที่เป็นค่าที่เราประกาศเอง
		local lastP, lastT
		while alive() do
			local ok = pcall(function()
				local c = LocalPlayer.Character
				local hum = c and c:FindFirstChildOfClass("Humanoid")
				local hrp = c and c:FindFirstChild("HumanoidRootPart")
				local S = Hub.Stats or {}
				local st = Hub.ACState

				-- ความเร็วเชิงตำแหน่งจริงระหว่างสองบรรทัด
				local realSpd = -1
				local now = os.clock()
				if hrp and lastP and lastT and now > lastT then
					realSpd = (hrp.Position - lastP).Magnitude / (now - lastT)
				end
				if hrp then lastP, lastT = hrp.Position, now end

				local ev = st and rawget(st, "Evidence")
				buf[#buf + 1] = ("%.0f %s|xz %d,%d|hp %s|ws %.1f|vDecl %.0f|vReal %.0f"
					.. "|threat %s|evS %s|evT %s|vr %s|mode %s|sup %s|lock %s"
					.. "|imp %s|col %s|dead %s|got %s|f %s|%s")
					:format(
						now - t0,
						tostring(Hub.Phase),
						hrp and hrp.Position.X or 0, hrp and hrp.Position.Z or 0,
						hum and math.floor(hum.Health) or -1,
						hum and hum.WalkSpeed or -1,
						hrp and hrp.AssemblyLinearVelocity.Magnitude or -1,
						realSpd,
						st and tostring(rawget(st, "ThreatLevel")) or "?",
						ev and tostring(rawget(ev, "Speed")) or "?",
						ev and tostring(rawget(ev, "Teleport")) or "?",
						st and tostring(rawget(st, "LastViolationReason")) or "?",
						st and tostring(rawget(st, "MovementMode")) or "?",
						st and tostring(rawget(st, "IsSupportedNow")) or "?",
						st and tostring(rawget(st, "ValidationLocked")) or "?",
						st and tostring(rawget(st, "ImpulseContext") ~= nil) or "?",
						hrp and tostring(hrp.CanCollide) or "?",
						hum and tostring(hum:GetStateEnabled(Enum.HumanoidStateType.Dead)) or "?",
						tostring(S.stolen), tostring(S.failed),
						-- จำนวนครั้งที่ยิง placeF สะสม  ใช้ดูว่ายิงถี่เกินจนโดนตัวจำกัดอัตราไหม
						-- ตัวเลขไล่สาเหตุการเตะ  ทุกตัวมีอยู่ในโค้ดแล้วแต่ไม่เคยถูกเขียนลงไฟล์
						-- เดาจากภาพหน้าจอมาหลายรอบแล้วผิดทุกรอบ เพราะข้อมูลไม่ได้ถูกบันทึก
						--
						-- vio   ไคลเอนต์ยิงรายงานความผิดขึ้นเซิร์ฟไปกี่ครั้ง (ต้องมี net true ก่อน)
						-- net   ติดตั้งตัวเฝ้าสำเร็จไหม  false = เลข vio ไม่มีความหมาย
						-- gui   ScreenGui ของเราไปอยู่ในอะไร
						--         ที่ซ่อนของ executor = ปลอดภัย
						--         PlayerGui = โค้ดเกมธรรมดาไล่อ่านเจอได้ ไม่ต้องมีสิทธิ์พิเศษ
						-- fell  หลุดใต้แมพแล้วถูกดึงกลับกี่ครั้ง (ดึงกลับ = วาปขึ้น 80 studs เฟรมเดียว)
						-- pinsk ตัวตรึงถูกข้ามกี่ครั้ง  ไม่ใช่ 0 = PinHold ปิดอยู่จริง
						-- tries acState สแกนพลาดอยู่กี่รอบ  ค้างที่ 1 = ตัวนับพัง วนสแกนไม่หยุด
						-- arm   ปลดเพดานสำเร็จไปกี่ครั้ง
						-- ev    อีเวนต์ที่กำลังทำงาน (- = ไม่มี)  ของบนแมพเปลี่ยนตามตัวนี้
						-- lane  เลนที่ใช้อยู่ / ระยะห่างจากของที่ขวางใกล้สุด
						-- tread ติดสถานะลูกวิ่งอยู่ไหม / ปลดสำเร็จไปกี่ครั้ง
						-- dgr   หลักฐานที่ระบบกันโกงสะสมไว้ สูงสุดที่เคยแตะ / ชะลอไปกี่ครั้ง
						--       0 ตลอด = ImpulseContext ปลอมยังติดอยู่  ขึ้นเมื่อไหร่คือมันหลุด
						-- allow ความเร็วที่ระบบยอมให้ไอดีนี้จริงๆ ตอนนั้น
						("place %s|ev %s|lane %s/%s|tread %s/%s|dgr %.2f/%s|allow %s|vio %s|net %s|gui %s|fell %s|pinsk %s|tries %s|arm %s|%s"):format(
							tostring(Hub.PlaceCalls or 0),
							(Hub.EventSig ~= nil and Hub.EventSig ~= "" and Hub.EventSig) or "-",
							tostring(math.floor(Hub.LaneZ or 0)),
							tostring(math.floor(Hub.LaneClear or -1)),
							tostring(Hub.TreadmillActive == true),
							tostring(Hub.TreadFixed or 0),
							tonumber(Hub.DangerPeak) or 0,
							tostring(Hub.BrakeHits or 0),
							tostring(math.floor(Hub.AllowedSpeed or -1)),
							tostring(Hub.ViolationFires or 0),
							tostring(Hub.NetHooked == true),
							(Hub.OverlayGui and Hub.OverlayGui.Parent
								and Hub.OverlayGui.Parent.ClassName) or "NIL",
							tostring(Hub.FellOff or 0),
							tostring(Hub.PinSkipped or 0),
							tostring(Hub.ACStateTries or 0),
							tostring(Hub.ImpulseArmed or 0),
							tostring(Hub.LastCarryMsg)))
				if #buf > MAX then table.remove(buf, 1) end
				-- เขียนทับทั้งไฟล์ทุกครั้ง ไฟล์จึงไม่โตไม่จำกัด
				writefile(TRACE, table.concat(buf, "\n"))
			end)
			if not ok then break end
			-- 1 วินาที ไม่ใช่ 2  ยิ่งถี่ยิ่งได้ภาพใกล้วินาทีที่โดนเตะ
			task.wait(1)
		end
	end)
end

-- ล้างของที่รุ่นเก่าอาจทิ้งค้างไว้ในตัวละคร
--
-- สองอย่างนี้ replicate ขึ้นเซิร์ฟเวอร์ ถ้าค้างอยู่คือลายเซ็นโกงติดตัวไปเรื่อยๆ
-- แม้รุ่นใหม่จะไม่ได้สั่งอะไรเลยก็ตาม  ต้องคืนค่าให้ตั้งแต่โหลด
pcall(function() setNoclip(false) end)
pcall(function()
	local c = LocalPlayer.Character
	local hum = c and c:FindFirstChildOfClass("Humanoid")
	if hum and not hum:GetStateEnabled(Enum.HumanoidStateType.Dead) then
		hum:SetStateEnabled(Enum.HumanoidStateType.Dead, true)
	end
end)

-- เปิดของที่ควรเปิดตั้งแต่โหลด  แต่ต้องรอให้การเชื่อมต่อนิ่งก่อน
--
-- ทำไมต้องรอ: ลูกค้าหลายคนรายงานว่า "แค่รันก็โดนเตะ" และ
-- "ถ้าเอาสคริปต์ค่ายอื่นมารันก่อน กลับรันได้ปกติ"
--
-- ผมไปอ่านสคริปต์นั้นแล้ว (Speed Hub X) ทั้งไฟล์มี 12 บรรทัด:
--     local Games = loadstring(HttpGet(game, ".../GameList.lua"))()
--     local URL = Games[GameId]
--     if not URL then return end        <- เกมไม่อยู่ในรายการ = ไม่ทำอะไรเลย
-- มันไม่แตะ WalkSpeed / Humanoid / CFrame / รีโมท อะไรเลยแม้แต่ตัวเดียว
--
-- สิ่งเดียวที่มันให้คือ "การถ่วงเวลา" (ดึง HTTP สองรอบก่อนเราจะเริ่ม)
-- = ยืนยันว่าปัญหาเป็นเรื่องจังหวะเวลา ไม่ใช่การเปลี่ยนสถานะอะไรในเกม
--
-- ตัวหนักสุดคือ fpsBoost ซึ่งวน workspace:GetDescendants() ของทั้งฉาก
-- (คอมเมนต์ในตัวมันเขียนเองว่า "ฉากนี้มีของเป็นหมื่นชิ้น")
-- แล้วเขียน property ใส่ทุกชิ้น  ของเดิมรันที่ 2 วินาทีหลังโหลด
-- ซึ่งอยู่กลางช่วงที่การเชื่อมต่อยังไม่นิ่งพอดี
local function waitSettled(extra)
	-- รอตัวละครเกิดและมีเลือดก่อน  ไม่ใช่แค่ game:IsLoaded()
	local t0 = os.clock()
	while os.clock() - t0 < 30 do
		local c = LocalPlayer.Character
		local hum = c and c:FindFirstChildOfClass("Humanoid")
		if hum and hum.Health > 0 then break end
		task.wait(0.25)
	end
	task.wait(math.max(0, tonumber(extra) or 0))
end

-- ตัวเฝ้าช่องเซิร์ฟต้องติดตั้งทันที ห้ามรอ StartupGrace
--
-- สองเหตุผล: (1) มันเบามาก แค่ require กับเขียนตาราง 2 ช่อง ไม่กระทบจังหวะเข้าเกม
-- (2) ถ้าติดช้ากว่าที่ระบบกันโกงยิงรายงานครั้งแรก เราจะไม่เห็นครั้งนั้นเลย
--    ซึ่งคือครั้งที่สำคัญที่สุด เพราะลูกค้าหลายคนโดนเตะภายในไม่กี่วินาทีแรก
pcall(Hub.watchNetwork)

-- ต่อสัญญาณลูกวิ่งทันที ห้ามรอ StartupGrace
-- ถ้าต่อช้ากว่าครั้งแรกที่เกมยิงมา เราจะพลาดครั้งนั้นแล้วติดสถานะค้างโดยไม่รู้ตัว
pcall(Hub.watchTreadmill)

-- ต่อสัญญาณสถานะถือไข่ทันทีเช่นกัน  ต่อช้าคือพลาดครั้งแรกแล้วนับผิดทั้งรอบ
pcall(Hub.watchCarry)

task.spawn(function()
	waitSettled(tonumber(Config.StartupGrace) or 15)

	-- ตอนโหลด โมดูล Network อาจยังไม่ถูก require  ลองซ้ำหลังทุกอย่างนิ่ง
	if not Hub.NetHooked then pcall(Hub.watchNetwork) end

	if Config.SmoothCam then pcall(startSmoothCam) end
	if Config.PerfMode then pcall(applyPerfSettings) end

	if Config.FpsBoost then
		-- ทำหลังสุด เพราะหนักที่สุด  และหน่วงเพิ่มอีกชั้น
		task.wait(3)
		local ok, n = pcall(Hub.fpsBoost)
		if ok then log(("เร่งเฟรม: ตัดของออก %d ชิ้น"):format(n or 0)) end
	end

	if Config.BlankScreen then pcall(Hub.setBlankScreen, true) end
end)

-- เริ่มฟาร์มเองถ้าสั่งไว้
-- หน่วงนิดนึงให้ UI/ตัวละคร/ข้อมูลเกมพร้อมก่อน ไม่งั้นรอบแรกพลาดฟรี
if Config.AutoStart then
	task.spawn(function()
		task.wait(3)
		if not alive() then return end
		Config.Running = true
		if setRunToggle then setRunToggle(true) end   -- ให้สวิตช์ใน UI ขยับตามด้วย
		log(("เริ่มฟาร์มอัตโนมัติ | %s | %d studs/s"):format(
			Config.Area, math.floor(Config.Step / Config.Gap)))
	end)
end

log("พร้อมใช้งาน — Hamster Diwa")
log("ทดสอบแล้ว: Hamster ของดีบอกต่อ")

-- บอกให้ชัดว่าค่าที่ใช้อยู่มาจากไหน เวลาแก้แล้วไม่เปลี่ยนจะได้รู้ว่าโดนตัวไหนทับ
-- ตอนนี้เหลือได้แค่สองอย่างเท่านั้น ไม่มีชั้นที่มาจากไฟล์บนเครื่องแล้ว
local configSource = globalConfigLoaded and "_G.HamsterConfig" or "ค่าเริ่มต้น"

log("ค่าที่ใช้มาจาก: " .. configSource)
if purged > 0 then
	log(("ลบไฟล์คอนฟิกเก่าที่ค้างในเครื่องทิ้งแล้ว %d ไฟล์"):format(purged))
end
if not globalConfigLoaded then
	log("ไม่พบ _G.HamsterConfig - กำลังใช้ค่าเริ่มต้นล้วน ตรวจว่ารันผ่าน loader หรือยัง")
end
log(("โหมด %s · %d studs/s · ด่าน %s"):format(
	Config.MoveMode, math.floor(Config.Step / Config.Gap), Config.Area))

print(("[Hamsterdiwa · Steal An Egg] โหลดเสร็จ | UI: %s | คอนฟิกจาก: %s | กด RightControl ซ่อน/โชว์"):format(
	usingLibrary and "Venoz Eiei" or "ในตัว", configSource))
